export type Merge<A, B> = {
  [K in keyof A | keyof B]: K extends keyof B ? B[K] : K extends keyof A ? A[K] : never;
};
export interface ZodType<T> {
  _output: T;
}
export interface ZodObject<T> extends ZodType<T> {
  extend<U>(shape: { [K in keyof U]: ZodType<U[K]> }): ZodObject<Merge<T, U>>;
}
export declare const z: {
  object<T>(shape: { [K in keyof T]: ZodType<T[K]> }): ZodObject<T>;
  string(): ZodType<string>;
  number(): ZodType<number>;
};
export type infer<T extends ZodType<unknown>> = T["_output"];
